Consider the Best-of-three on  $G(2n,p,q)$ such that $p$ and $q$ are positive constants.
If $\frac{q}{p}>\frac{1}{7}$, then $G(2n,p,q)$ w.h.p.~satisfies the following property:

There exist two positive constants $C,C'>0$ such that 
\begin{align*}
\forall A\subseteq V\, :\, \mathop{\mathbf{Pr}}\left[T_{\mathrm{cons}}(A)\leq C\log n \right] \geq 1-O\left(n^{-C'}\right).
\end{align*}

Consider the Best-of-two on $G(2n,p,q)$ such that $p$ and $q$ are positive constants.
If $\frac{q}{p}>\sqrt{5}-2$, then $G(2n,p,q)$ w.h.p.~satisfies the following property:

There exist two positive constants $C,C'>0$ such that 
\begin{align*}
\forall A\subseteq V\, :\, \mathop{\mathbf{Pr}}\left[T_{\mathrm{cons}}(A)\leq C\log n \right] \geq 1-O\left(n^{-C'}\right).
\end{align*}

Consider the Best-of-three on $G(2n,p,q)$ such that $r\mathrel{\mathop:}= \frac{q}{p}$ is a constant.

\begin{enumerate}[label=(\roman*)]
\item
If $r>\frac{1}{7}$, then $G(2n,p,q)$ w.h.p.~satisfies the following property:

There exist two positive constants $C, C'>0$ such that
\begin{align*}
&\forall A\subseteq V\text{ of $\bigl||A|-|V\setminus A|\bigr|= \Omega(n)$}
:\\
&\mathop{\mathbf{Pr}}\left[T_{\mathrm{cons}}(A)\leq C\left(\log\log n+\frac{\log n}{\log(np)}\right)\right] \geq 1-O\left(n^{-C'}\right).
\end{align*}







\item 
If $r<\frac{1}{7}$, then $G(2n,p,q)$ w.h.p.~satisfies the following property:

There exist a set $A\subseteq V$ with $\bigl||A|-|V\setminus A|\bigr|= \Omega(n)$ and two positive constants $C, C'>0$ such that
\begin{align*}


\mathop{\mathbf{Pr}}\left[T_{\mathrm{cons}}(A) \geq \exp(Cn) \right] \geq 1-O\left(n^{-C'}\right).
\end{align*}







\end{enumerate}

Consider the Best-of-two on $G(2n,p,q)$ such that $r\mathrel{\mathop:}= \frac{q}{p}$ is a constant.

\begin{enumerate}[label=(\roman*)]
\item
If $r>\sqrt{5}-2$, then $G(2n,p,q)$ w.h.p.~satisfies the following property:

There exist two positive constants $C, C'>0$ such that
\begin{align*}
&\forall A\subseteq V\text{ of $\bigl||A|-|V\setminus A|\bigr|= \Omega(n)$}
:\\
&\mathop{\mathbf{Pr}}\left[T_{\mathrm{cons}}(A)\leq C\left(\log\log n+\frac{\log n}{\log(np)}\right)\right] \geq 1-O\left(n^{-C'}\right).
\end{align*}

\item





If $r<\sqrt{5}-2$, then $G(2n,p,q)$ w.h.p.~satisfies the following property:

There exist a set $A\subseteq V$ with $\bigl||A|-|V\setminus A|\bigr|= \Omega(n)$ and two positive constants $C, C'>0$ such that
\begin{align*}


\mathop{\mathbf{Pr}}\left[T_{\mathrm{cons}}(A) \geq \exp(Cn) \right] \geq 1-O\left(n^{-C'}\right).
\end{align*}
\end{enumerate}

Consider an $(f_1,f_2)$-polynomial voting process on an $f_1$-good and $f_2$-good $G(2n,p,q)$ such that $r=\frac{q}{p}$ is a constant.
Let $H$ be the induced dynamical system.
Then, for any sink point $\mathbf{a}^*$ and any sufficiently small $\epsilon=\omega(\sqrt{1/np})$,
\begin{align*}
\mathop{\mathbf{Pr}}\left[{\boldsymbol \alpha}'\not\in B(\mathbf{a}^*,\epsilon)\,\middle|\,{\boldsymbol \alpha}\in B(\mathbf{a}^*,\epsilon)\right]\leq \exp(-\Omega(\epsilon^2 n))
\end{align*}
holds.

In particular, let 
\begin{align*}
\tau:=\inf\left\{t\in\mathbb{N}:{\boldsymbol \alpha}^{(t)}\not\in B(\mathbf{a}^*,\epsilon)\right\}
\end{align*}
be a stopping time.
Then, $\tau\geq\exp(\Omega(\epsilon^2 n))$ holds w.h.p.~conditioned on ${\boldsymbol \alpha}^{(0)}\in B(\mathbf{a}^*,\epsilon)$ for any $\epsilon$ satisfying $\epsilon=\omega(\max\{1/\sqrt{np},\sqrt{\log n/n}\})$.

Consider an $(f_1,f_2)$-polynomial voting process on an $f_1$-good and $f_2$-good $G(2n,p,q)$ such that $\frac{p}{q}$ is a constant.
Suppose that the Jacobian matrix at the point ${\boldsymbol \alpha}=(0,0)$ is the all-zero matrix.

Then, there exists a constant $C_1,C_2,\delta>0$ such that
\begin{align*}
\mathop{\mathbf{Pr}}\left[T_{\mathrm{cons}}(A)\leq C_1\left(\log\log n+\frac{\log n}{\log np}\right)\right]\geq 1-n^{-C_2}
\end{align*}
for all $A\subseteq V$ satisfying $|A|\leq \delta n$.

For a given set $[M]=\{1,2, \ldots, M\}$, let $I_1, I_2, \ldots, I_M$ be independent binary random variables.


Now, let $\mathcal{E}\subseteq 2^{[M]}$ be a collection of subsets of $[M]$ ($F\subseteq [M]$ for all $F\in \mathcal{E}$) and let
\begin{align*}
Y=\sum_{F\in \mathcal{E}}w(F)\prod_{e\in F}I_e,
\end{align*}
where $w(F)$ are positive coefficients.

For a subset $A\subseteq [M]$, define $Y_{A}$ as
\begin{align*}
Y_{A}=\sum_{\substack{F\in\mathcal{E}:\\F\supseteq A}} w(F)\prod_{e\in F\setminus A}I_e.
\end{align*}
If the polynomial $Y$ has degree at most $k$ (i.e.~$\max_{F\in\mathcal{E}}|F|\leq k$), then for any positive $\lambda>1$, it holds that
\begin{align*}
\mathop{\mathbf{Pr}}\left[|Y-\mathbf{E}[Y]|\geq \sqrt{k! \max_{A\subseteq [M]}\mathbf{E}[Y_{A}]\max_{A\subseteq [M]:A\neq \emptyset}\mathbf{E}[Y_{A}]}(8\lambda)^k\right]\leq 2\exp(2+(k-1)\log M-\lambda).
\end{align*}
